/**
 * Retorna o devocional para a data especificada (formato YYYY-MM-DD).
 * Se não houver registro exato pelo ano, busca por mês e dia (MM-DD) ou
 * utiliza o acervo clássico do Pão Diário para garantir 100% de disponibilidade.
 */
function getDevotionalForDate(dateStr) {
  if (!dateStr) {
    const d = new Date();
    dateStr = d.toISOString().split('T')[0];
  }

  // 1. Procura por data exata ISO (ex: 2026-09-29)
  if (DEVOTIONAL_DATABASE[dateStr]) {
    return DEVOTIONAL_DATABASE[dateStr];
  }

  // 2. Procura pelo mês e dia (ex: 09-29)
  const mmdd = dateStr.slice(5);
  if (DEVOTIONAL_DATABASE[mmdd]) {
    const devo = { ...DEVOTIONAL_DATABASE[mmdd] };
    devo.dateIso = dateStr;
    devo.date = formatDevotionalDateDisplay(dateStr);
    return devo;
  }

  // 3. Fallback inteligente: calcula dia do ano e seleciona do acervo clássico Pão Diário
  const parts = dateStr.split('-').map(Number);
  const d = new Date(parts[0], parts[1] - 1, parts[2]);
  const startOfYear = new Date(parts[0], 0, 1);
  const dayOfYear = Math.floor((d - startOfYear) / (24 * 60 * 60 * 1000));
  const classicIdx = Math.abs(dayOfYear) % DEVOTIONAL_CLASSICS_POOL.length;
  const classic = DEVOTIONAL_CLASSICS_POOL[classicIdx];

  return {
    ...classic,
    dateIso: dateStr,
    date: formatDevotionalDateDisplay(dateStr),
    url: 'https://paodiario.org'
  };
}

/**
 * Formata data ISO para texto por extenso elegante em Português
 */
function formatDevotionalDateDisplay(isoStr) {
  if (!isoStr) return '';
  const parts = isoStr.split('-').map(Number);
  const dateObj = new Date(parts[0], parts[1] - 1, parts[2]);
  const weekdays = ['Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'];
  const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
  
  const weekday = weekdays[dateObj.getDay()];
  const day = parts[2];
  const month = months[parts[1] - 1];
  const year = parts[0];

  return `${weekday}, ${day} de ${month} de ${year}`;
}

/**
 * Retorna todas as datas que têm devocionais específicos registados
 */
function getAvailableDevotionalDates() {
  const dates = [];
  for (const k in DEVOTIONAL_DATABASE) {
    if (k.length === 10 && k.includes('-')) {
      dates.push(k);
    }
  }
  return dates.sort();
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    DEVOTIONAL_DATABASE,
    DEVOTIONAL_CLASSICS_POOL,
    getDevotionalForDate,
    formatDevotionalDateDisplay,
    getAvailableDevotionalDates
  };
}
